# Quick stats check
print(f'Built {len(all_topics)} topics.')
for i, t in enumerate(all_topics):
    mq = len(t['quiz']['mcq'])
    vs = len(t['quiz']['very_short_1mark'])
    s2 = len(t['quiz']['short_2mark'])
    e4 = len(t['quiz']['evaluation_4mark'])
    e8 = len(t['quiz']['explanatory_8mark'])
    fc = len(t['flashcards'])
    tl = len(t['timeline'])
    ce = len(t['cause_effect'])
    br = len(t['simple_breakdown'])
    vw = len(t['voice_script'].split())
    print(f'  T{i+1}: MCQ={mq} VS={vs} S2={s2} E4={e4} E8={e8} Cards={fc} TL={tl} CE={ce} BD={br} Voice={vw}w')

from score_topic import score
results = []
for i, t in enumerate(all_topics):
    ok, ai = score(t, f'CH4 T{i+1}')
    results.append((ok, ai))
    print(f'T{i+1}: AI={ai:.1f} {"✅" if ok and ai>=9.0 else "❌"}')

if all(ok and ai >= 9.0 for ok, ai in results):
    print(f'\n✅ All {len(all_topics)} topics pass! Generating seed file...')
    fname = generate('ch4', 'chapter4', 'শিল্পবিপ্লব ও সাম্রাজ্যবাদ', 4, all_topics)
    print(f'Generated: {fname}')
else:
    print(f'\n❌ Some topics failed - see above')
